interface SidebarProps {
  isOpen: boolean;
  toggleSidebar: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ isOpen, toggleSidebar }) => {
  const pathname = usePathname();

  const navLinks = [
    { href: "/vendor/dashboard", label: "Dashboard", icon: <DashboardIcon /> },
    { href: "/vendor/dashboard/halls", label: "Halls", icon: <HallIcon /> },
    { href: "/vendor/dashboard/bookings", label: "Bookings", icon: <BookingIcon /> },
    { href: "/vendor/dashboard/analytics", label: "Analytics", icon: <AnalyticsIcon /> },
    { href: "/vendor/dashboard/staff", label: "Staff", icon: <StaffIcon /> },
    { href: "/vendor/dashboard/settings", label: "Settings", icon: <SettingsIcon /> },
  ];

  return (
    <div className={`bg-primary text-white flex flex-col transition-all duration-300 ${isOpen ? "w-64" : "w-20"}`}>
      <div className="flex items-center justify-between h-20 px-4">
        <span className={`text-2xl font-bold ${!isOpen && "hidden"}`}>HallBooker</span>
        <button onClick={toggleSidebar} className="text-white p-2 rounded-lg hover:bg-white hover:bg-opacity-20">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
            </svg>
        </button>
      </div>
      <nav className="flex-1 px-4 py-4 space-y-2">
        {navLinks.map((link) => (
          <Link
            key={link.href}
            href={link.href}
            className={`flex items-center p-2 text-base font-normal rounded-lg transition-colors duration-200 hover:bg-secondary ${pathname === link.href ? "bg-secondary" : ""}`}
            title={link.label}
          >
            <div className="flex-shrink-0">{link.icon}</div>
            <span className={`ml-3 whitespace-nowrap transition-opacity duration-300 ${!isOpen && "opacity-0 hidden"}`}>{link.label}</span>
          </Link>
        ))}
      </nav>
    </div>
  );
};

export default Sidebar;
